// API配置
const CONFIG = {
  accountName: '饼干哥哥AGI',
  apiKey: 'JZLdc9670be1403c05c',
  baseUrl: 'https://www.dajiala.com/fbmain/monitor/v3/post_history',
  maxPages: 5,
  delayMs: 2000
};

// 飞书配置（已预填）
const FEISHU_CONFIG = {
  appId: 'cli_a907365bcefbdbd2',
  appSecret: 'UOnIdOt4xWAgLrzVJUmrQbAOu8Icetjv'
};

return [{
  json: {
    config: CONFIG,
    feishu: FEISHU_CONFIG,
    currentPage: 1,
    allArticles: [],
    totalCost: 0
  }
}];

const tokenData = $input.all()[0].json;
const articleData = $input.all()[1].json;

// 合并数据
return [{
  json: {
    ...$input.all()[1].json,
    feishuToken: tokenData.tenant_access_token
  }
}];

const response = $input.first().json;

if (response.code !== 0) {
  if (response.code === 110 || response.code === 115) {
    return [{json: {...$input.first().json, hasMore: false}}];
  }
  throw new Error(`API错误: ${response.msg}`);
}

const articles = response.data || [];
const totalPage = response.total_page || 1;
const currentPage = $input.first().json.currentPage;
const allArticles = $input.first().json.allArticles || [];
const maxPages = $input.first().json.config.maxPages;

// 去重
const existingIds = new Set(allArticles.map(a => a.appmsgid));
const newArticles = articles.filter(a => !existingIds.has(a.appmsgid));
allArticles.push(...newArticles);

const hasMore = currentPage < Math.min(totalPage, maxPages);

console.log(`第 ${currentPage} 页: ${newArticles.length} 篇新文章，累计 ${allArticles.length} 篇`);

return [{
  json: {
    ...$input.first().json,
    articles: newArticles,
    allArticles,
    totalPages: totalPage,
    hasMore,
    nextPage: currentPage + 1,
    remainMoney: response.remain_money,
    totalCost: ($input.first().json.totalCost || 0) + (response.cost_money || 0)
  }
}];

// 生成文档内容
const data = $input.first().json;
const articles = data.allArticles;

// 按日期分组
const grouped = {};
articles.forEach(article => {
  const date = article.post_time_str.split(' ')[0];
  if (!grouped[date]) grouped[date] = [];
  grouped[date].push(article);
});

// 生成Markdown内容
let content = `# 📝 饼干哥哥AGI 文章汇总\n\n`;
content += `> 📊 **统计信息**\n`;
content += `> - 抓取时间: ${new Date().toLocaleString()}\n`;
content += `> - 文章总数: ${articles.length} 篇\n`;
content += `> - 总费用: ${data.totalCost.toFixed(2)} 元\n`;
content += `> - 账户余额: ${data.remainMoney} 元\n\n`;
content += `---\n\n`;

// 按日期倒序
Object.keys(grouped).sort((a, b) => new Date(b) - new Date(a)).forEach(date => {
  content += `## 📅 ${date}\n\n`;
  grouped[date].forEach((article, idx) => {
    content += `### ${idx + 1}. ${article.title}\n\n`;
    content += `- 📝 **摘要**: ${article.digest || '暂无摘要'}\n`;
    content += `- ⏰ **发布时间**: ${article.post_time_str}\n`;
    content += `- 🔗 **原文链接**: [点击阅读](${article.url})\n`;
    content += `- 🖼️ **封面**: ![封面](${article.cover_url})\n`;
    content += `- 🏷️ **类型**: ${article.original === 1 ? '✅ 原创' : article.original === 2 ? '🔄 转载' : '❓ 未声明'}\n`;
    content += `- 📍 **位置**: 第${article.position}条\n\n`;
  });
  content += `---\n\n`;
});

return [{
  json: {
    ...data,
    docTitle: `饼干哥哥AGI-文章汇总-${new Date().toISOString().split('T')[0]}`,
    docContent: content,
    articleCount: articles.length
  }
}];

const data = $input.first().json;
const createResponse = $input.all()[1]?.json || {};

// 获取文档token
const docToken = createResponse.data?.token || createResponse.token;

if (!docToken) {
  console.log('创建文档响应:', JSON.stringify(createResponse, null, 2));
  throw new Error('无法获取文档token');
}

return [{
  json: {
    ...data,
    docToken,
    docUrl: `https://www.feishu.cn/docx/${docToken}`
  }
}];

const data = $input.first().json;

return [{
  json: {
    status: 'success',
    docTitle: data.docTitle,
    docUrl: data.docUrl,
    articleCount: data.articleCount,
    totalCost: data.totalCost,
    message: `✅ 成功创建飞书文档！\n📄 标题: ${data.docTitle}\n🔗 链接: ${data.docUrl}\n📊 文章数: ${data.articleCount} 篇\n💰 费用: ${data.totalCost.toFixed(2)} 元`
  }
}];
